async function guardarEdit(){
  const now=new Date().toISOString();
  const razon=document.getElementById('eRazon').value.trim();
  if(!razon){ alert('La razón social es obligatoria'); return; }
  try{
    let pid=EDIT;
    const total=parseInt(document.getElementById('eHabTotal').value)||0;
    const simples=parseInt(document.getElementById('eHabSimples').value)||0;
    const dobles=parseInt(document.getElementById('eHabDobles').value)||0;
    let simplesBanio=parseInt(document.getElementById('eHabSimplesBanio').value)||0;
    let doblesBanio=parseInt(document.getElementById('eHabDoblesBanio').value)||0;
    if(simples>0 && simplesBanio>simples) simplesBanio=simples;
    if(dobles>0 && doblesBanio>dobles) doblesBanio=dobles;
    const provData={ razon_social:razon, nombre_fantasia:document.getElementById('eFantasia').value.trim(),
      rut_empresa:document.getElementById('eRut').value.trim(), localidad:document.getElementById('eLocalidad').value.trim(),
      direccion:document.getElementById('eDireccion').value.trim(), correo_empresa:document.getElementById('eCorreo').value.trim(),
      fono_empresa:document.getElementById('eFono').value.trim(), descripcion_general:document.getElementById('eDesc').value.trim(),
      updated_at:now };

    if(NUEVO_HOTEL){
      // crear proveedor nuevo (es_hoteleria lo fuerza el trigger por rubro; lo marcamos explícito)
      pid='hot_'+Date.now().toString(36);
      const ins={ proveedor_id:pid, ...provData, rubros_norm:'Hotelería / Hospedaje', giros_sii:'Hospedaje',
        es_hoteleria:true, estado_registro:'Activo', created_by:document.getElementById('uName').textContent, fuente:'mgi' };
      const {error:eIns}=await SB.from('proveedores').insert(ins); if(eIns) throw eIns;
      const nuevo={...ins}; DATA.push(nuevo);
    } else {
      const p=DATA.find(x=>x.proveedor_id===pid); if(!p){ alert('No se encontró el proveedor'); return; }
      const {error:e1}=await SB.from('proveedores').update(provData).eq('proveedor_id',pid); if(e1)throw e1;
      Object.assign(p,provData);
    }

    // contacto principal
    const cs=CONT[pid]||[]; let cp=cs.find(c=>String(c.principal).toUpperCase()==='TRUE')||cs[0];
    const cdata={ nombre:document.getElementById('ecNombre').value.trim(), cargo:document.getElementById('ecCargo').value.trim(), fono:document.getElementById('ecFono').value.trim(), correo:document.getElementById('ecCorreo').value.trim() };
    if(cp && cp.contacto_id){ await SB.from('contactos').update(cdata).eq('contacto_id',cp.contacto_id); Object.assign(cp,cdata); }
    else if(cdata.nombre){ const cid='cont_'+pid+'_0'; await SB.from('contactos').insert({contacto_id:cid,proveedor_id:pid,...cdata,principal:'TRUE',estado_registro:'Activo'}); (CONT[pid]=CONT[pid]||[]).push({contacto_id:cid,proveedor_id:pid,...cdata,principal:'TRUE'}); }

    // hotelería: incluye contratos + servicios + total
    const json=JSON.stringify({total,contratos:CONTRATOS,servicios:SERVS,simples_banio:simplesBanio,dobles_banio:doblesBanio});
    // Upsert por hotel_id (evita "duplicate key hoteleria_pkey": el delete no
    // borraba por RLS/trigger y el insert chocaba con la PK existente).
    await SB.from('hoteleria').upsert({hotel_id:'hot_'+pid,proveedor_id:pid,hab_simples:simples,hab_dobles:dobles,contratos_json:json,estado_registro:'Activo',updated_at:now},{onConflict:'hotel_id'});
    HOT[pid]={total,simples,dobles,simples_banio:simplesBanio,dobles_banio:doblesBanio,contratos:CONTRATOS.slice(),servicios:SERVS.slice()};

    // log
    try{ await SB.from('registro_ediciones').insert({usuario_email:USER.email,usuario_nombre:document.getElementById('uName').textContent,entidad:'proveedor_mgi',entidad_id:pid,accion:NUEVO_HOTEL?'crear':'editar',detalle:(NUEVO_HOTEL?'Creó hotel ':'Editó hotelería de ')+razon}); }catch(e){}
    cerrarEdit(); render();
    alert(NUEVO_HOTEL?'✅ Hotel creado':'✅ Cambios guardados');
  }catch(e){ alert('Error al guardar: '+e.message); }
}

