// ═══ GESTOR DE CRITERIOS DE ESTANDARIZACIÓN (crear/editar/asignar por rubro, con hitos) ═══
const EST_RUBROS_G=['Hotelería','Lavandería','Alimentación'];
const EST_ICONOS_G=['⚡','🐀','📐','🏥','🧯','🚿','🔥','💧','🧺','🍽','🏨','🛠','📄','✅','🔒','♻️','🌡️','🧹'];
let GESTOR_RUBRO='Hotelería', _gIconoData='';
function estHitosG(c){ try{ const h=JSON.parse(c.hitos_json||'[]'); return Array.isArray(h)?h:[]; }catch(e){ return []; } }
async function abrirGestorCriterios(){
  if(!window.ES_ADMIN_MGI && !(USER)){ alert('Inicia sesión'); return; }
  GESTOR_RUBRO=ESTM_RUBRO[MGI_SECCION]||'Hotelería';
  if(!ESTM.loaded) await estmCargar();
  document.getElementById('gestorModal').style.display='flex';
  renderGestor();
}
function cerrarGestorCriterios(){ document.getElementById('gestorModal').style.display='none'; }
function renderGestor(){
  document.getElementById('gestorRubroTabs').innerHTML=EST_RUBROS_G.map(r=>{
    const on=GESTOR_RUBRO===r; const ico={'Hotelería':'🏨','Lavandería':'🧺','Alimentación':'🍽'}[r];
    return `<button onclick="GESTOR_RUBRO='${r}';renderGestor()" style="padding:9px 18px;border-radius:10px;border:2px solid #5b4fcf;background:${on?'#5b4fcf':'#fff'};color:${on?'#fff':'#5b4fcf'};font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:.95rem;text-transform:uppercase;cursor:pointer">${ico} ${r}</button>`;
  }).join('');
  const crits=ESTM.criterios.filter(c=>c.rubro===GESTOR_RUBRO).sort((a,b)=>a.nombre.localeCompare(b.nombre));
  const sumP=crits.reduce((a,c)=>a+(+c.ponderacion||0),0);
  let h='';
  if(sumP!==100) h+=`<div style="background:#fff3cd;color:#8a6100;border-radius:8px;padding:8px 12px;font-size:.8rem;font-weight:700;margin-bottom:12px">⚠ Las ponderaciones del rubro suman ${sumP}% (ideal 100%)</div>`;
  h+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:12px">';
  crits.forEach(c=>{
    const hitos=estHitosG(c);
    const icoHtml=(c.icono||'📋').startsWith('data:')?`<img src="${c.icono}" style="width:30px;height:30px;object-fit:contain">`:`<span style="font-size:1.5rem">${c.icono||'📋'}</span>`;
    h+=`<div style="background:#f7f6fd;border:1px solid var(--border);border-radius:12px;padding:14px 16px">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">${icoHtml}
        <div style="flex:1;font-weight:700;font-size:.92rem">${esc(c.nombre)}</div>
        <b onclick="gDelCriterio('${c.id}')" style="cursor:pointer;color:#c0311b" title="Eliminar">✕</b></div>
      <div style="display:flex;align-items:center;gap:7px;font-size:.78rem;color:var(--text-muted);margin-bottom:8px">Ponderación:
        <input type="number" min="0" max="100" value="${c.ponderacion||0}" onchange="gSetPond('${c.id}',this.value)" style="width:58px;border:1px solid var(--border);border-radius:6px;padding:4px 6px;text-align:center"> %</div>
      <div style="font-size:.72rem;font-weight:700;color:#4338ca;text-transform:uppercase;margin-bottom:4px">Hitos (suman 100%)</div>
      ${hitos.map((ht,i)=>`<div style="display:flex;align-items:center;gap:6px;font-size:.8rem;margin-bottom:4px">
        <span style="flex:1">${esc(ht.n)}</span>
        <input type="number" min="0" max="100" step="10" value="${ht.p||0}" onchange="gSetHitoPct('${c.id}',${i},this.value)" style="width:54px;border:1px solid var(--border);border-radius:5px;padding:3px 5px;text-align:center;font-size:.78rem"> %
        <b onclick="gDelHito('${c.id}',${i})" style="cursor:pointer;color:#c0311b;font-size:.85rem">✕</b></div>`).join('')}
      <div style="display:flex;gap:5px;margin-top:6px">
        <input id="gnh_${c.id}" placeholder="Nuevo hito..." style="flex:1;border:1px solid var(--border);border-radius:6px;padding:5px 8px;font-size:.78rem">
        <input id="gnhp_${c.id}" type="number" min="0" max="100" step="10" placeholder="%" style="width:52px;border:1px solid var(--border);border-radius:6px;padding:5px 5px;font-size:.78rem;text-align:center">
        <button onclick="gAddHito('${c.id}')" style="background:#5b4fcf;color:#fff;border:none;border-radius:6px;padding:5px 10px;font-size:.78rem;font-weight:700;cursor:pointer">＋</button></div>
    </div>`;
  });
  // card nuevo criterio
  h+=`<div style="background:#f3f1fb;border:2px dashed #5b4fcf;border-radius:12px;padding:14px 16px">
    <div style="font-weight:700;font-size:.88rem;color:#5b4fcf;margin-bottom:8px">＋ Nuevo criterio de ${GESTOR_RUBRO}</div>
    <input id="gNcNombre" placeholder="Nombre del criterio..." style="width:100%;border:1px solid var(--border);border-radius:7px;padding:7px 10px;font-size:.85rem;margin-bottom:7px">
    <div style="display:flex;align-items:center;gap:6px;margin-bottom:7px;flex-wrap:wrap">
      <select id="gNcIcono" style="border:1px solid var(--border);border-radius:7px;padding:6px;font-size:1rem">${EST_ICONOS_G.map(i=>`<option>${i}</option>`).join('')}</select>
      <label style="font-size:.74rem;color:#5b4fcf;cursor:pointer;text-decoration:underline">o subir icono<input type="file" accept="image/*" style="display:none" onchange="gIconoArchivo(this)"></label>
      <span id="gNcIconoPrev"></span>
      <input id="gNcPond" type="number" min="0" max="100" placeholder="Pond. %" style="width:80px;border:1px solid var(--border);border-radius:7px;padding:6px;font-size:.82rem;text-align:center">
    </div>
    <button onclick="gAddCriterio()" style="background:#5b4fcf;color:#fff;border:none;border-radius:8px;padding:8px 16px;font-weight:700;cursor:pointer;font-size:.85rem">＋ Crear criterio</button>
  </div></div>
  <div style="font-size:.75rem;color:var(--text-muted);margin-top:12px">💡 Un mismo criterio puede existir en los 3 rubros (créalo en cada uno) o solo en uno. El avance por proveedor se marca desde la ficha de cada proveedor.</div>`;
  document.getElementById('gestorBody').innerHTML=h;
}
function gIconoArchivo(input){
  const file=input.files[0]; if(!file) return;
  const rd=new FileReader();
  rd.onload=e=>{ const img=new Image(); img.onload=()=>{ const cv=document.createElement('canvas'); const m=64; const sc=Math.min(1,m/Math.max(img.width,img.height)); cv.width=Math.round(img.width*sc); cv.height=Math.round(img.height*sc); cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height); _gIconoData=cv.toDataURL('image/png'); document.getElementById('gNcIconoPrev').innerHTML='<img src="'+_gIconoData+'" style="width:26px;height:26px;vertical-align:middle">'; }; img.src=e.target.result; };
  rd.readAsDataURL(file);
}
async function gAddCriterio(){
  const nom=(document.getElementById('gNcNombre').value||'').trim(); if(!nom){ alert('Escribe el nombre'); return; }
  const icono=_gIconoData||document.getElementById('gNcIcono').value||'📋';
  const pond=Math.max(0,Math.min(100,parseInt(document.getElementById('gNcPond').value)||0));
  const id='ec_'+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
  const {error}=await SB.from('est_criterios').insert({id,nombre:nom,rubro:GESTOR_RUBRO,icono,ponderacion:pond,hitos_json:'[]',updated_by:miNombreMGI(),updated_at:new Date().toISOString()});
  if(error){ alert('Error: '+error.message); return; }
  _gIconoData=''; await estmCargar(); renderGestor();
}
async function gSetPond(cid,val){
  const n=Math.max(0,Math.min(100,parseInt(val)||0));
  await SB.from('est_criterios').update({ponderacion:n,updated_at:new Date().toISOString()}).eq('id',cid);
  const c=ESTM.criterios.find(x=>x.id===cid); if(c) c.ponderacion=n; renderGestor();
}
async function gAddHito(cid){
  const c=ESTM.criterios.find(x=>x.id===cid); if(!c) return;
  const nom=(document.getElementById('gnh_'+cid).value||'').trim(); if(!nom){ alert('Nombre del hito'); return; }
  const p=Math.max(0,Math.min(100,parseInt(document.getElementById('gnhp_'+cid).value)||10));
  const hitos=estHitosG(c); hitos.push({n:nom,p});
  const suma=hitos.reduce((a,x)=>a+(+x.p||0),0);
  if(suma>100){ alert('Los hitos superan 100% ('+suma+'%)'); return; }
  await SB.from('est_criterios').update({hitos_json:JSON.stringify(hitos),updated_at:new Date().toISOString()}).eq('id',cid);
  c.hitos_json=JSON.stringify(hitos); renderGestor();
}
async function gSetHitoPct(cid,i,val){
  const c=ESTM.criterios.find(x=>x.id===cid); if(!c) return;
  const hitos=estHitosG(c); if(!hitos[i]) return;
  hitos[i].p=Math.max(0,Math.min(100,parseInt(val)||0));
  await SB.from('est_criterios').update({hitos_json:JSON.stringify(hitos),updated_at:new Date().toISOString()}).eq('id',cid);
  c.hitos_json=JSON.stringify(hitos); renderGestor();
}
async function gDelHito(cid,i){
  const c=ESTM.criterios.find(x=>x.id===cid); if(!c) return;
  const hitos=estHitosG(c); hitos.splice(i,1);
  await SB.from('est_criterios').update({hitos_json:JSON.stringify(hitos),updated_at:new Date().toISOString()}).eq('id',cid);
  c.hitos_json=JSON.stringify(hitos); renderGestor();
}
async function gDelCriterio(cid){
  if(!confirm('¿Eliminar este criterio para todo el rubro?')) return;
  const {error}=await SB.from('est_criterios').update({estado_registro:'Eliminado',updated_at:new Date().toISOString()}).eq('id',cid);
  if(error){ alert('Solo admin puede eliminar: '+error.message); return; }
  await estmCargar(); renderGestor();
}

// ═══ ESTANDARIZACIÓN (tabla compartida con index) ═══
let EST_PID=null;
async function abrirEstandarizacionMGI(pid){
  const p=DATA.find(x=>x.proveedor_id===pid); if(!p) return;
  EST_PID=pid;
  if(!ESTM.loaded) await estmCargar();
  document.getElementById('estProvNombre').textContent=dispName(p)+' · '+(p.localidad||'');
  document.getElementById('estModal').style.display='flex';
  renderEstProvMGI();
}
function cerrarEstandarizacionMGI(){ document.getElementById('estModal').style.display='none'; EST_PID=null; }
function estAvanceMGI(pid,c){
  const av=ESTM.avances.find(a=>a.proveedor_id===pid&&a.criterio_id===c.id);
  let done=[]; if(av){ try{ done=JSON.parse(av.hitos_done||'[]'); }catch(e){} }
  const hitos=estHitosG(c);
  if(!hitos.length) return done.includes(0)?100:0;
  const tot=hitos.reduce((a,h)=>a+(+h.p||0),0)||100;
  return Math.round(hitos.reduce((a,h,i)=>a+(done.includes(i)?(+h.p||0):0),0)/tot*100);
}
function renderEstProvMGI(){
  const pid=EST_PID; const p=DATA.find(x=>x.proveedor_id===pid); if(!p) return;
  const rubro=ESTM_RUBRO[MGI_SECCION];
  const crits=ESTM.criterios.filter(c=>c.rubro===rubro).sort((a,b)=>a.nombre.localeCompare(b.nombre));
  const pct=estmPctProv(pid,rubro); const col=pct>=80?'#1e7e34':pct>=50?'#b8860b':'#c0311b';
  document.getElementById('estResumen').innerHTML=`<div style="background:#f3f1fb;border-radius:10px;padding:12px 16px;display:flex;align-items:center;gap:14px">
    <div style="font-size:1.7rem;font-weight:800;color:${col}">${pct}%</div>
    <div style="flex:1"><div style="font-size:.78rem;font-weight:700;color:#4338ca;text-transform:uppercase">Avance en ${rubro}</div>
    <div style="height:9px;background:#e0e0e0;border-radius:5px;margin-top:5px;overflow:hidden"><div style="height:100%;width:${pct}%;background:${col};border-radius:5px"></div></div></div></div>`;
  let h='';
  if(!crits.length) h='<div style="font-size:.85rem;color:var(--text-muted)">No hay criterios definidos para '+rubro+'. Créalos en "Gestionar criterios".</div>';
  crits.forEach(c=>{
    const hitos=estHitosG(c);
    const av=ESTM.avances.find(a=>a.proveedor_id===pid&&a.criterio_id===c.id);
    let done=[]; if(av){ try{ done=JSON.parse(av.hitos_done||'[]'); }catch(e){} }
    const pctC=estAvanceMGI(pid,c);
    const icoH=(c.icono||'📋').startsWith('data:')?`<img src="${c.icono}" style="width:20px;height:20px;object-fit:contain;vertical-align:middle">`:c.icono||'📋';
    h+=`<div style="background:#f7f6fd;border-radius:9px;padding:10px 12px;margin-bottom:7px">
      <div style="font-size:.85rem;font-weight:700">${icoH} ${esc(c.nombre)} <span style="color:${pctC>=80?'#1e7e34':pctC>=50?'#b8860b':'#c0311b'}">· ${pctC}%</span> <span style="font-weight:400;font-size:.7rem;color:var(--text-muted)">(pond. ${c.ponderacion||0}%)</span></div>
      <div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:5px">
      ${hitos.length?hitos.map((ht,i)=>`<label style="display:inline-flex;align-items:center;gap:5px;background:${done.includes(i)?'#e6f4ea':'#fff'};border:1px solid ${done.includes(i)?'#1e7e34':'#ddd'};border-radius:14px;padding:4px 10px;font-size:.75rem;cursor:pointer"><input type="checkbox" ${done.includes(i)?'checked':''} onchange="estToggleHitoMGI('${pid}','${c.id}',${i})" style="width:auto">${esc(ht.n)} (${ht.p}%)</label>`).join(''):`<label style="display:inline-flex;align-items:center;gap:5px;background:${done.includes(0)?'#e6f4ea':'#fff'};border:1px solid ${done.includes(0)?'#1e7e34':'#ddd'};border-radius:14px;padding:4px 10px;font-size:.75rem;cursor:pointer"><input type="checkbox" ${done.includes(0)?'checked':''} onchange="estToggleHitoMGI('${pid}','${c.id}',0)" style="width:auto">Completado (100%)</label>`}
      </div></div>`;
  });
  document.getElementById('estLista').innerHTML=h;
}
async function estToggleHitoMGI(provId,cid,i){
  const avId='av_'+provId+'_'+cid;
  let av=ESTM.avances.find(a=>a.id===avId);
  let done=[]; if(av){ try{ done=JSON.parse(av.hitos_done||'[]'); }catch(e){} }
  const ix=done.indexOf(i); if(ix>=0) done.splice(ix,1); else done.push(i);
  const payload={id:avId,proveedor_id:provId,criterio_id:cid,hitos_done:JSON.stringify(done),estado_registro:'Activo',updated_by:miNombreMGI(),updated_at:new Date().toISOString()};
  const {error}=await SB.from('est_avance').upsert(payload,{onConflict:'id'});
  if(error){ alert('Error: '+error.message); return; }
  if(av){ av.hitos_done=JSON.stringify(done); } else ESTM.avances.push(payload);
  renderEstProvMGI();
  renderEstKPI(filtered());
}

// ── FICHA EMERGENTE ─────────────────────────────────────────────────────────
// Misma estructura y estética que la ficha de Proveedores: cabecera con
// acciones, pestañas y cuerpo a dos columnas. Los estilos son los mismos
// (shared/css/ficha-modal.css); acá solo cambia QUÉ se muestra, porque MGI
// gestiona hospedaje (habitaciones, contratos, trabajadores) en vez de
// rubros y maquinaria.
//
// No duplica lógica: las visitas y los trabajadores los cargan las mismas
// funciones que ya usaba el modal de edición (cargarVisitasMGI /
// cargarTrabajadoresMGI), apuntando a los contenedores de la ficha.
let FICHA_TAB = 'datos';
let FICHA_PID = null;

